public object FfiConverterTypeNymTransportClient: FfiConverter<NymTransportClient, Pointer> {
    override fun lower(value: NymTransportClient): Pointer = value.callWithPointer { it }

    override fun lift(value: Pointer): NymTransportClient {
        return NymTransportClient(value)
    }

    override fun read(buf: ByteBuffer): NymTransportClient {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: NymTransportClient) = 8

    override fun write(value: NymTransportClient, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}




