public object FfiConverterOptionalTypeRendezvousMessage: FfiConverterRustBuffer<RendezvousMessage?> {
    override fun read(buf: ByteBuffer): RendezvousMessage? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterTypeRendezvousMessage.read(buf)
    }

    override fun allocationSize(value: RendezvousMessage?): Int {
        if (value == null) {
            return 1
        } else {
            return 1 + FfiConverterTypeRendezvousMessage.allocationSize(value)
        }
    }

    override fun write(value: RendezvousMessage?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterTypeRendezvousMessage.write(value, buf)
        }
    }
}




public object FfiConverterSequenceUByte: FfiConverterRustBuffer<List<UByte>> {
    override fun read(buf: ByteBuffer): List<UByte> {
        val len = buf.getInt()
        return List<UByte>(len) {
            FfiConverterUByte.read(buf)
        }
    }

    override fun allocationSize(value: List<UByte>): Int {
        val sizeForLength = 4
        val sizeForItems = value.map { FfiConverterUByte.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<UByte>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.forEach {
            FfiConverterUByte.write(it, buf)
        }
    }
}




